do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-102';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: The Story of the New Testament$j$, $j${"prompt": "Write an essay of about 500 words titled The Story of the New Testament. In your essay: (1) Tell who Jesus Christ is and what He did, using at least two Gospel events, such as His birth, His teaching, His miracles, His cross and His resurrection. (2) Explain how the church began in the book of Acts, naming at least two people such as Peter, Stephen or Paul. (3) Choose at least two letters from Romans to Jude and explain one main message from each. (4) Tell what the book of Revelation teaches about the future and about hope. (5) Quote at least three verses from the King James Version with their references. (6) Close by telling what the New Testament means for your own life as a student at New Life Preparatory Academy.", "rubric": "Total 100. Gospels: accurate account of who Jesus is and what He did: 20. Acts: accurate account of the beginning of the church with at least two people named: 15. Letters: two letters with a correct main message from each: 20. Revelation: accurate summary of its message of hope: 10. Scripture: at least three verses quoted correctly with references: 15. Personal application: 10. Organization, clear writing and correct conventions: 10."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: The Story of the New Testament$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: New Testament Survey$j$, $j${"questions": [{"q": "How many books are in the New Testament?", "options": ["Twenty seven", "Sixty six", "Twenty one", "Thirty nine"]}, {"q": "Which four books are the Gospels?", "options": ["Acts, Romans, James and Jude", "Matthew, Mark, Luke and John", "Luke, Acts, John and Peter", "Matthew, Hebrews, James and John"]}, {"q": "In which town was Jesus born?", "options": ["Capernaum", "Bethlehem", "Jericho", "Nazareth"]}, {"q": "On which day did Jesus rise from the dead?", "options": ["The fortieth day", "The first day He was buried", "The seventh day", "The third day"]}, {"q": "According to Acts 1:8, what did Jesus say the disciples would receive when the Holy Ghost came upon them?", "options": ["Power", "A new law", "A kingdom", "Riches"]}, {"q": "What did Peter tell the crowd at Pentecost to do in Acts 2:38?", "options": ["Repent and be baptized in the name of Jesus Christ", "Leave Jerusalem", "Return to the temple", "Pay tithes"]}, {"q": "Who was the first Christian martyr?", "options": ["Barnabas", "James", "Stephen", "Philip"]}, {"q": "What happened to Saul on the road to Damascus?", "options": ["He saw a vision of an angel", "He met the risen Jesus and was changed", "He was arrested", "He was shipwrecked"]}, {"q": "Where were the disciples first called Christians?", "options": ["Antioch", "Rome", "Corinth", "Jerusalem"]}, {"q": "According to Romans 6:23, what is the gift of God?", "options": ["Eternal life through Jesus Christ our Lord", "A seat in the temple", "A long life on earth", "Wealth"]}, {"q": "According to 1 Corinthians 13:13, which is the greatest of faith, hope and charity?", "options": ["Hope", "Faith", "Charity", "They are all equal"]}, {"q": "What does the book of Galatians teach about how a person is justified?", "options": ["By being born in Israel", "By paying tithes", "By works of the law", "By faith in Jesus Christ"]}, {"q": "According to Ephesians 2:8, by what are we saved through faith?", "options": ["Good works", "The law", "Grace", "Our own goodness"]}, {"q": "Which letter of Paul is known as the letter of joy?", "options": ["Philemon", "Colossians", "Titus", "Philippians"]}, {"q": "What does 2 Timothy 3:16 say about all scripture?", "options": ["It is given by inspiration of God", "It is hard to understand", "It was written only for priests", "It is only history"]}, {"q": "According to Hebrews 11:1, what is faith?", "options": ["A good feeling", "A reward for good works", "A kind of luck", "The substance of things hoped for, the evidence of things not seen"]}, {"q": "According to James 2:26, what is faith without works?", "options": ["Strong", "Complete", "Dead", "Hidden"]}, {"q": "According to 1 John 4:8, what is God?", "options": ["King", "Love", "Rock", "Judge"]}, {"q": "What did Jesus say in Revelation 3:20?", "options": ["Wait for the end of the age", "Build a wall around the church", "Behold, I stand at the door, and knock", "Leave the city"]}, {"q": "What does Revelation 21:4 promise about the new heaven and new earth?", "options": ["A return to the old law", "No more death, sorrow, crying or pain", "A world without any people", "A new temple of stone"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: New Testament Survey$j$);
end
$seed$;
